const QUERIES = ["evidence", "shortcut", "nodes", "grammar", "informs", "supports", "index"];
const resultsOf = async (page) =>
  page.locator(".bp3-menu .bp3-menu-item").evaluateAll((els) =>
    els.map((el) => el.innerText.replace(/\s*\n\s*/g, " — ").trim()),
  );

export default {
  async ready({ page }) {
    return page.locator("input[placeholder='Search settings']").isVisible();
  },
  async run({ page, outDir }) {
    const input = page.locator("input[placeholder='Search settings']");
    const out = {};
    for (const q of QUERIES) {
      await input.fill(q);
      await page.waitForTimeout(300);
      out[q] = await resultsOf(page);
      await page.screenshot({ path: `${outDir}/search-${q}.png` });
    }
    await input.fill("color");
    await page.waitForTimeout(300);
    out.color = await resultsOf(page);
    const target = page.locator(".bp3-menu .bp3-menu-item", { hasText: /Evidence\s*›\s*Color/ }).first();
    const fallback = page.locator(".bp3-menu .bp3-menu-item").first();
    await ((await target.count()) ? target : fallback).click();
    await page.waitForTimeout(450);
    out.flash = await page.evaluate(() => {
      const el = document.querySelector(".bg-gray-100.-mx-2");
      if (!el) return null;
      const cs = getComputedStyle(el);
      return { cls: el.className, margin: cs.margin, padding: cs.padding, bg: cs.backgroundColor };
    });
    await page.locator(".bp3-dialog").last().screenshot({ path: `${outDir}/flash-highlight.png` });
    return out;
  },
};
