const settingsDialog = (page) => page.locator(".bp3-dialog").filter({ has: page.locator("input[placeholder='Search settings']") });
// Rects of matched elements relative to the dialog's box, in px.
const rects = async (page, dialogLoc, selectorFn) =>
  page.evaluate(([fnSrc, dialogBox]) => {
    const els = new Function("return (" + fnSrc + ")()")();
    return els.filter(Boolean).map((el) => {
      const r = el.getBoundingClientRect();
      return { x: Math.round(r.left - dialogBox.x), y: Math.round(r.top - dialogBox.y), w: Math.round(r.width), h: Math.round(r.height), text: (el.innerText || "").slice(0, 40) };
    });
  }, [selectorFn.toString(), await dialogLoc.boundingBox()]);

export default {
  async ready({ page }) { return page.locator("input[placeholder='Search settings']").isVisible(); },
  async run({ page, outDir }) {
    const out = {};
    const d = settingsDialog(page);
    const input = page.locator("input[placeholder='Search settings']");
    const snap = async (name, fn) => { await page.waitForTimeout(450); out[name] = { size: await d.boundingBox(), rects: fn ? await rects(page, d, fn) : [] }; await d.screenshot({ path: `${outDir}/${name}.png` }); };

    await snap("a-sections", () => [document.querySelector(".dg-settings-tabs .bp3-tab-list"),
      ...[...document.querySelectorAll(".dg-setting-row")].slice(0, 8).map((r) => r.querySelector(".bp3-icon, svg"))]);
    await input.fill("evidence"); await page.waitForTimeout(400);
    await snap("b-search", () => [document.querySelector("input[placeholder='Search settings']"), document.querySelector(".bp3-popover .bp3-menu, .bp3-menu")]);
    await input.fill("claim"); await page.waitForTimeout(400);
    await page.locator(".bp3-menu .bp3-menu-item", { hasText: /^\s*Claim\s*\n/ }).first().click().catch(async () => page.locator(".bp3-menu .bp3-menu-item").first().click());
    await page.waitForTimeout(1600);
    await snap("c-node-page", () => { const h = [...document.querySelectorAll(".bp3-dialog *")].find((e) => e.children.length === 0 && /Grammar\s*›\s*Nodes\s*›/.test(e.parentElement?.innerText || "") && e.innerText === "Nodes"); return [h?.closest("div")?.parentElement]; });
    await input.fill("claim color"); await page.waitForTimeout(400);
    await page.locator(".bp3-menu .bp3-menu-item").first().click();
    await page.waitForTimeout(250);
    out["d-jump"] = { size: await d.boundingBox(), rects: await rects(page, d, () => [document.querySelector(".bg-gray-100.-mx-2")]) };
    await d.screenshot({ path: `${outDir}/d-jump.png` });
    await page.waitForTimeout(1500);

    for (let i = 0; i < 3; i++) { await page.keyboard.press("Escape"); await page.waitForTimeout(200); }
    await page.evaluate(() => window.__dgPlaywrightCommandCallbacks?.["DG: Export - Current page"]?.());
    const ex = page.locator(".bp3-dialog").filter({ hasText: "Export options" }).last();
    await ex.waitFor({ timeout: 15000 });
    await ex.getByRole("button", { name: "Export options" }).click();
    await page.waitForTimeout(700);
    out["e-export"] = { size: await ex.boundingBox(), rects: await rects(page, ex, () => { const b = [...document.querySelectorAll(".bp3-dialog button")].find((x) => x.innerText.trim() === "Export options"); return [b, b?.parentElement?.nextElementSibling]; }) };
    await ex.screenshot({ path: `${outDir}/e-export.png` });
    return out;
  },
};
EOF
